import requests
import json

def fetch_repo(repo_id):
    url = f"https://api.github.com/repositories/{repo_id}"
    try:
        r = requests.get(url, timeout=10)
        if r.status_code == 200:
            return r.json()
        else:
            print(f"Repo {repo_id}: status {r.status_code}")
            return None
    except Exception as e:
        print(f"Repo {repo_id}: {e}")
        return None

repo_ids = [1, 1000, 1000000, 1000000000]
result = {}

for rid in repo_ids:
    data = fetch_repo(rid)
    if data:
        info = {
            "repo_name": data.get("name", ""),
            "owner": data.get("owner", {}).get("login", ""),
            "star_count": int(data.get("stargazers_count", 0)),
            "fork_count": int(data.get("forks_count", 0)),
            "creation_time": data.get("created_at", "").replace("+00:00", "Z") if data.get("created_at") else "",
            "description": data.get("description", ""),
            "language": data.get("language", ""),
            "repo_url": data.get("html_url", "")
        }
        result[str(rid)] = info
        print(f"Repo {rid}: {data['name']} by {info['owner']} - stars: {info['star_count']}")
    else:
        print(f"Skipping repo {rid}")

with open("/app/github_info.json", "w") as f:
    json.dump(result, f, indent=4)

print("\nSaved to /app/github_info.json")
print(json.dumps(result, indent=4))
PYEOF
